c.STDIO:
#include <stdio.h>

int main(void) {
    long long a, b;
    scanf("%lld%lld", &a, &b);
    if (b < 0) {
        a = -a;
        b = -b;
    }
    long long x = a < 0 ? -a : a;
    long long y = b;
    while (y != 0) {
        long long remainder = x % y;
        x = y;
        y = remainder;
    }
    printf("%lld %lld\n", a / x, b / x);
    return 0;
}

